# Adaptive Rejection Sampling (ARS) in R
# Reference: Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs sampling.

ars <- function(density_function, domain, n = 1000, x = NULL, lb = TRUE, ub = TRUE, max_points = 100) {
  # 1. Input Validation
  if (!is.function(density_function)) {
    stop("density_function must be a valid R function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 representing (lower, upper).")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n %% 1 != 0) {
    stop("n must be a positive integer representing sample count.")
  }

  # Initialize initial evaluation points if not provided
  # We need at least 2 points to start exponential upper hull, more is better.
  if (is.null(x)) {
    # Choose initial points inside domain
    # Handle infinite bounds safely
    lower <- domain[1]
    upper <- domain[2]
    if (is.infinite(lower)) lower <- -5
    if (is.infinite(upper)) upper <- 5
    if (lower >= upper) {
      lower <- -2
      upper <- 2
    }
    x <- sort(unique(c(lower, (lower + upper) / 2, upper)))
    # Ensure we have at least 3 points
    if (length(x) < 3) {
      x <- sort(unique(c(lower, lower + (upper - lower) * 0.25, lower + (upper - lower) * 0.75, upper))}
    }
  } else {
    x <- sort(unique(x))
    if (any(x < domain[1] | x > domain[2])) {
      stop("Initial points x must fall within domain.")
    }
    if (length(x) < 2) {
      stop("At least 2 initial points are required.")
    }
  }

  # Evaluate log density and derivatives (finite differences)
  # h(x) = log(f(x))
  eval_log_density <- function(pts) {
    vals <- density_function(pts)
    if (any(is.na(vals) | vals < 0)) {
      stop("Density function returned NA or negative values.")
    }
    # Avoid log(0)
    vals[vals == 0] <- .Machine$double.xmin
    log_vals <- log(vals)
    if (any(is.infinite(log_vals))) {
      stop("Log density resulted in infinite values.")
    }
    return(log_vals)
  }

  h <- eval_log_density(x)
  # Compute numerical derivative using central differences or forward/backward at bounds
  # h_prime(x_i)
  calc_derivatives <- function(pts, vals) {
    k <- length(pts)
    derivs <- numeric(k)
    for (i in 1:k) {
      if (i == 1) {
        derivs[i] <- (vals[2] - vals[1]) / (pts[2] - pts[1])
      } else if (i == k) {
        derivs[i] <- (vals[k] - vals[k-1]) / (pts[k] - pts[k-1])
      } else {
        derivs[i] <- (vals[i+1] - vals[i-1]) / (pts[i+1] - pts[i-1])
      }
    }
    return(derivs)
  }

  h_prime <- calc_derivatives(x, h)

  # Check log-concavity: chord between x_{i} and x_{i+1} must lie below tangent or derivatives must be non-increasing
  check_log_concavity <- function(pts, vals, derivs) {
    k <- length(pts)
    for (i in 1:(k - 1)) {
      # Secant slope
      sec_slope <- (vals[i+1] - vals[i]) / (pts[i+1] - pts[i])
      # For log-concave function, derivative should be non-increasing
      # Or slope of secant between i and i+1 should be <= derivative at i, and >= derivative at i+1
      # Allow small numerical tolerance
      if (derivs[i] < derivs[i+1] - 1e-5) {
        # Non-log-concave check triggered
        return(FALSE)
      }
    }
    return(TRUE)
  }

  if (!check_log_concavity(x, h, h_prime)) {
    stop("Error: Density function is not log-concave across initial points.")
  }

  # Helper to construct upper hull lines: u_i(x) = h(x_i) + h'(x_i)(x - x_i)
  # Intersection of line i and i+1:
  # z_i = (h(x_{i+1}) - h(x_i) - h'(x_{i+1})x_{i+1} + h'(x_i)x_i) / (h'(x_i) - h'(x_{i+1}))

  update_hulls <- function(pts, vals, derivs) {
    k <- length(pts)
    z <- numeric(k + 1)
    z[1] <- domain[1]
    z[k + 1] <- domain[2]

    for (i in 1:(k - 1)) {
      denom <- derivs[i] - derivs[i+1]
      if (abs(denom) < 1e-12) {
        z[i+1] <- (pts[i] + pts[i+1]) / 2
      } else {
        z[i+1] <- (vals[i+1] - vals[i] - derivs[i+1]*pts[i+1] + derivs[i]*pts[i]) / denom
        # Ensure z[i+1] is between pts[i] and pts[i+1]
        if (z[i+1] < pts[i] || z[i+1] > pts[i+1]) {
          z[i+1] <- (pts[i] + pts[i+1]) / 2
        }
      }
    }
    return(z)
  }

  samples <- numeric(n)
  count <- 0

  while (count < n) {
    z <- update_hulls(x, h, h_prime)
    k <- length(x)

    # Calculate area under upper hull exponential pieces
    # u(x) on [z_i, z_{i+1}] is exp(h(x_i) + h'(x_i)(x - x_i))
    # Integral I_i = int_{z_i}^{z_{i+1}} exp(h(x_i) + h'(x_i)(x - x_i)) dx
    integrals <- numeric(k)
    for (i in 1:k) {
      hi <- h[i]
      hpi <- h_prime[i]
      zi <- z[i]
      zip1 <- z[i+1]
      if (abs(hpi) < 1e-12) {
        integrals[i] <- exp(hi) * (zip1 - zi)
      } else {
        integrals[i] <- (exp(hi) / hpi) * (exp(hpi * (zip1 - pts[i])) - exp(hpi * (zi - pts[i])))
      }
      if (is.na(integrals[i]) || integrals[i] < 0) integrals[i] <- 0
    }

    total_integral <- sum(integrals)
    if (total_integral <= 0 || is.na(total_integral)) {
      stop("Upper hull integral calculation failed or is zero.")
    }

    # Sample interval index based on normalized integrals
    probs <- integrals / total_integral
    interval_idx <- sample.int(k, size = 1, prob = probs)

    # Sample x* from truncated exponential distribution on [z_i, z_{i+1}]
    hi <- h[interval_idx]
    hpi <- h_prime[interval_idx]
    zi <- z[interval_idx]
    zip1 <- z[interval_idx+1]
    xi <- x[interval_idx]

    # Inverse CDF sampling for truncated exponential
    u_rand <- runif(1)
    if (abs(hpi) < 1e-12) {
      x_star <- zi + u_rand * (zip1 - zi)
    } else {
      # CDF at zi is exp(hpi * (zi - xi))
      # CDF at zip1 is exp(hpi * (zip1 - xi))
      term1 <- exp(hpi * (zi - xi))
      term2 <- exp(hpi * (zip1 - xi))
      x_star <- xi + (1 / hpi) * log(term1 + u_rand * (term2 - term1))
    }

    if (is.na(x_star) || x_star < domain[1] || x_star > domain[2]) {
      next
    }

    # Evaluate log density at x_star
    h_star <- eval_log_density(x_star)

    # Check log-concavity dynamically during sampling if new point violates concavity
    # Find insertion position
    pos <- findInterval(x_star, x)
    # Check consistency with neighbors
    if (pos > 0 && pos < length(x)) {
      slope_left <- (h_star - h[pos]) / (x_star - x[pos])
      slope_right <- (h[pos+1] - h_star) / (x[pos+1] - x_star)
      if (slope_left < slope_right - 1e-4) {
        stop(paste0("Non-log-concave density detected at sample x = ", x_star))
      }
    }

    # Lower hull evaluation (s(x) is piecewise linear connecting (x_i, h(x_i))
    # Lower hull s(x) is -Inf outside [x_1, x_k]
    s_star <- -Inf
    if (x_star >= x[1] && x_star <= x[k]) {
      if (pos == 0) pos <- 1
      if (pos >= k) pos <- k - 1
      # Linear interpolation between x[pos] and x[pos+1]
      t_val <- (x_star - x[pos]) / (x[pos+1] - x[pos])
      s_star <- (1 - t_val) * h[pos] + t_val * h[pos+1]
    }

    # Upper hull value at x_star
    u_star <- hi + hpi * (x_star - xi)

    # Squeeze step / rejection test
    w <- runif(1)
    accepted <- FALSE

    if (w <= exp(s_star - u_star)) {
      # Lower hull test passed directly
      accepted <- TRUE
    } else {
      # Evaluate true density acceptance
      if (w <= exp(h_star - u_star)) {
        accepted <- TRUE
      }
    }

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }

    # Update adaptive set with x_star regardless of acceptance (standard ARS practice)
    if (!(x_star %in% x)) {
      x <- c(x, x_star)
      ord <- order(x)
      x <- x[ord]
      h <- eval_log_density(x)
      h_prime <- calc_derivatives(x, h)

      # Verify log concavity of updated set
      if (!check_log_concavity(x, h, h_prime)) {
        stop("Error: Non-log-concave density encountered during hull expansion.")
      }

      if (length(x) > max_points) {
        # Trim points if too many to maintain performance, keeping bounds and extremes
        keep <- unique(c(1, floor(length(x)/2), length(x)))
        # Or keep most recently added points / evenly spaced
        x <- x[seq(1, length(x), by = max(1, floor(length(x) / 30)))]
        h <- eval_log_density(x)
        h_prime <- calc_derivatives(x, h)
      }
    }
  }

  return(samples)
}

