    }
    if (length(x) < 2) {
      stop("At least 2 initial points are required.")
    }
  }

  # Evaluate log density and derivatives (finite differences)
  eval_log_density <- function(pts) {
    vals <- density_function(pts)
    if (any(is.na(vals) | vals < 0)) {
      stop("Density function returned NA or negative values.")
    }
    vals[vals == 0] <- .Machine$double.xmin
    log_vals <- log(vals)
    if (any(is.infinite(log_vals))) {
      stop("Log density resulted in infinite values.")
    }
    return(log_vals)
  }

  h <- eval_log_density(x)
  calc_derivatives <- function(pts, vals) {
    k <- length(pts)
    derivs <- numeric(k)
    for (i in 1:k) {
      if (i == 1) {
        derivs[i] <- (vals[2] - vals[1]) / (pts[2] - pts[1])
      } else if (i == k) {
        derivs[i] <- (vals[k] - vals[k-1]) / (pts[k] - pts[k-1])
      } else {
        derivs[i] <- (vals[i+1] - vals[i-1]) / (pts[i+1] - pts[i-1])
      }
    }
    return(derivs)
  }

  h_prime <- calc_derivatives(x, h)

  check_log_concavity <- function(pts, vals, derivs) {
    k <- length(pts)
    for (i in 1:(k - 1)) {
      if (derivs[i] < derivs[i+1] - 1e-5) {
        return(FALSE)
      }
    }
    return(TRUE)
  }

  if (!check_log_concavity(x, h, h_prime)) {
    stop("Error: Density function is not log-concave across initial points.")
  }

  update_hulls <- function(pts, vals, derivs) {
    k <- length(pts)
    z <- numeric(k + 1)
    z[1] <- domain[1]
    z[k + 1] <- domain[2]

    for (i in 1:(k - 1)) {
      denom <- derivs[i] - derivs[i+1]
      if (abs(denom) < 1e-12) {
        z[i+1] <- (pts[i] + pts[i+1]) / 2
      } else {
        z[i+1] <- (vals[i+1] - vals[i] - derivs[i+1]*pts[i+1] + derivs[i]*pts[i]) / denom
        if (z[i+1] < pts[i] || z[i+1] > pts[i+1]) {
          z[i+1] <- (pts[i] + pts[i+1]) / 2
        }
      }
    }
    return(z)
  }

  samples <- numeric(n)
  count <- 0

  while (count < n) {
    z <- update_hulls(x, h, h_prime)
    k <- length(x)

    integrals <- numeric(k)
    for (i in 1:k) {
      hi <- h[i]
      hpi <- h_prime[i]
      zi <- z[i]
      zip1 <- z[i+1]
      xi_val <- x[i]
      if (abs(hpi) < 1e-12) {
        integrals[i] <- exp(hi) * (zip1 - zi)
      } else {
        integrals[i] <- (exp(hi) / hpi) * (exp(hpi * (zip1 - xi_val)) - exp(hpi * (zi - xi_val)))
      }
      if (is.na(integrals[i]) || integrals[i] < 0) integrals[i] <- 0
    }

    total_integral <- sum(integrals)
    if (total_integral <= 0 || is.na(total_integral)) {
      stop("Upper hull integral calculation failed or is zero.")
    }

    probs <- integrals / total_integral
    interval_idx <- sample.int(k, size = 1, prob = probs)

    hi <- h[interval_idx]
    hpi <- h_prime[interval_idx]
    zi <- z[interval_idx]
    zip1 <- z[interval_idx+1]
    xi <- x[interval_idx]

    u_rand <- runif(1)
    if (abs(hpi) < 1e-12) {
      x_star <- zi + u_rand * (zip1 - zi)
    } else {
      term1 <- exp(hpi * (zi - xi))
      term2 <- exp(hpi * (zip1 - xi))
      x_star <- xi + (1 / hpi) * log(term1 + u_rand * (term2 - term1))
    }

    if (is.na(x_star) || x_star < domain[1] || x_star > domain[2]) {
      next
    }

    h_star <- eval_log_density(x_star)

    pos <- findInterval(x_star, x)
    if (pos > 0 && pos < length(x)) {
      slope_left <- (h_star - h[pos]) / (x_star - x[pos])
      slope_right <- (h[pos+1] - h_star) / (x[pos+1] - x_star)
      if (slope_left < slope_right - 1e-4) {
        stop(paste0("Non-log-concave density detected at sample x = ", x_star))
      }
    }

    s_star <- -Inf
    if (x_star >= x[1] && x_star <= x[k]) {
      if (pos == 0) pos <- 1
      if (pos >= k) pos <- k - 1
      t_val <- (x_star - x[pos]) / (x[pos+1] - x[pos])
      s_star <- (1 - t_val) * h[pos] + t_val * h[pos+1]
    }

    u_star <- hi + hpi * (x_star - xi)

    w <- runif(1)
    accepted <- FALSE

    if (w <= exp(s_star - u_star)) {
      accepted <- TRUE
    } else {
      if (w <= exp(h_star - u_star)) {
        accepted <- TRUE
      }
    }

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }

    if (!(x_star %in% x)) {
      x <- c(x, x_star)
      ord <- order(x)
      x <- x[ord]
      h <- eval_log_density(x)
      h_prime <- calc_derivatives(x, h)

      if (!check_log_concavity(x, h, h_prime)) {
        stop("Error: Non-log-concave density encountered during hull expansion.")
      }

      if (length(x) > max_points) {
        x <- x[seq(1, length(x), by = max(1, floor(length(x) / 30)))]
        h <- eval_log_density(x)
        h_prime <- calc_derivatives(x, h)
      }
    }
  }

  return(samples)
}

test <- function() {
  cat("Running Adaptive Rejection Sampling (ARS) tests...\n\n")
  all_passed <- TRUE

  set.seed(42)
  tryCatch({
    norm_samples <- ars(function(z) dnorm(z, mean = 0, sd = 1), domain = c(-4, 4), n = 1000)
    mean_val <- mean(norm_samples)
    sd_val <- sd(norm_samples)

    if (abs(mean_val) < 0.2 && abs(sd_val - 1) < 0.2) {
      cat(sprintf("NORMAL_TEST: PASS (mean: %.4f, sd: %.4f)\n", mean_val, sd_val))
      writeLines(as.character(norm_samples), "/app/normal_samples.txt")
    } else {
      cat(sprintf("NORMAL_TEST: FAIL (mean: %.4f, sd: %.4f)\n", mean_val, sd_val))
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("NORMAL_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  set.seed(42)
  tryCatch({
    exp_samples <- ars(function(z) dexp(z, rate = 1), domain = c(0.01, 10), n = 1000)
    mean_val <- mean(exp_samples)
    sd_val <- sd(exp_samples)

    if (abs(mean_val - 1) < 0.2 && abs(sd_val - 1) < 0.2) {
      cat(sprintf("EXPONENTIAL_TEST: PASS (mean: %.4f, sd: %.4f)\n", mean_val, sd_val))
      writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
    } else {
      cat(sprintf("EXPONENTIAL_TEST: FAIL (mean: %.4f, sd: %.4f)\n", mean_val, sd_val))
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("EXPONENTIAL_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  tryCatch({
    ars(function(z) dnorm(z), domain = c(-3, 3), n = -10)
    cat("INPUT_VALIDATION_TEST: FAIL (Should have rejected negative n)\n")
    all_passed <- FALSE
  }, error = function(e) {
    cat("INPUT_VALIDATION_TEST: PASS (Correctly caught invalid input)\n")
  })

  tryCatch({
    ars(function(z) exp(z^2), domain = c(-2, 2), n = 100)
    cat("NON_LOG_CONCAVE_TEST: FAIL (Should have detected non-log-concave density)\n")
    all_passed <- FALSE
  }, error = function(e) {
    cat("NON_LOG_CONCAVE_TEST: PASS (Correctly detected non-log-concave density)\n")
  })

  if (all_passed) {
    cat("\nOVERALL_TEST_STATUS: PASS\n")
  } else {
    cat("\nOVERALL_TEST_STATUS: FAIL\n")
  }
}
